def rate_limit(capacity, refill_per_sec, requests):
    """requests: [[t_ms, client_id, cost], ...] in non-decreasing time. Each client has its own bucket,
    starting full. Tokens refill continuously at refill_per_sec, capped at capacity.
    Returns 1 (allowed, tokens deducted) or 0 (rejected, nothing deducted) per request.
    Uses exact integer arithmetic: tokens are tracked in millitoken units."""
    state = {}
    out = []
    cap = capacity * 1000
    for t, cid, cost in requests:
        tok, last = state.get(cid, (cap, t))
        tok = min(cap, tok + (t - last) * refill_per_sec)      # ms × tokens/s = millitokens
        if tok >= cost * 1000: tok -= cost * 1000; out.append(1)
        else: out.append(0)
        state[cid] = (tok, t)
    return out

