vector<int> rateLimit(int capacity, int rate, vector<vector<int>>& rq) {
    unordered_map<int, pair<long long, long long>> st; long long cap = 1000LL * capacity; vector<int> out;
    for (auto& r : rq) { long long t = r[0]; int c = r[1]; long long cost = 1000LL * r[2];
        auto it = st.find(c); long long tok = cap, last = t; if (it != st.end()) { tok = it->second.first; last = it->second.second; }
        tok = min(cap, tok + (t - last) * rate);
        if (tok >= cost) { tok -= cost; out.push_back(1); } else out.push_back(0);
        st[c] = {tok, t}; }
    return out;
}
